<div class="d-flex gap-2 align-items-center mb-3"><h2 class="h4 mb-0">الرسائل</h2><a class="btn btn-primary ms-auto" href="<?= url('messages/new') ?>"><i class="bi bi-pencil-square"></i> رسالة جديدة</a></div>
<div class="card-s"><?php if (!$threads): ?><div class="empty-state"><i class="bi bi-chat-dots"></i>لا توجد رسائل.</div><?php endif; ?><div class="list-group list-group-flush"><?php foreach ($threads as $t): ?><a class="list-group-item list-group-item-action bg-transparent d-flex gap-2 align-items-center" href="<?= url('messages/' . (int)$t['id']) ?>"><strong class="<?= (int)$t['unread'] ? '' : 'fw-normal' ?>"><?= e($t['subject']) ?></strong><small class="text-muted">بدأها <?= e($t['starter']) ?></small><?php if ((int)$t['unread']): ?><span class="badge text-bg-danger"><?= (int)$t['unread'] ?></span><?php endif; ?><small class="text-muted ms-auto" dir="ltr"><?= e($t['last_at']) ?></small></a><?php endforeach; ?></div></div>
